from pathlib import Path
import json,re,hashlib,subprocess,shutil,os
R=Path(__file__).resolve().parents[1];W=R/'build';O=R/'dist/2.3.0'
NODE=os.environ.get('REVISAWIKI_NODE')or shutil.which('node')or'node'
expected=json.loads((R/'tests/expected_release.json').read_text())
s=(O/'RevisaWiki_v2_3_completo.js').read_text()
assert hashlib.sha256(s.encode()).hexdigest()==expected['files']['RevisaWiki_v2_3_completo.js']['sha256']
data={'version':'2.3.0','schema':1,'catalogDate':'2026-10-14','packed':{}}
for pattern,key,replacement in [(r'^    const PACKED_PTWIKI_CATALOG = (.*);$','ptwiki','    const PACKED_PTWIKI_CATALOG = root.RevisaWikiDataV2.packed.ptwiki;'),(r'^    const TRANSLATION_RULES = unpackTranslationData\((.*)\);$','translations','    const TRANSLATION_RULES = unpackTranslationData(root.RevisaWikiDataV2.packed.translations);'),(r'^    const SPELLING_RULES = Object.freeze\(unpackSpellingRows\((.*)\)\);$','spelling','    const SPELLING_RULES = Object.freeze(unpackSpellingRows(root.RevisaWikiDataV2.packed.spelling));')]:
 m=re.search(pattern,s,re.M);assert m,key;data['packed'][key]=json.loads(m.group(1));s=s[:m.start()]+replacement+s[m.end():]
(O/'RevisaWiki_v2_3_dados.js').write_text('/* RevisaWiki 2.3.0, dados. CC BY-SA 4.0. */\n(function(root){const data='+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';if(typeof module === "object" && module.exports) module.exports=data;else root.RevisaWikiDataV2=data;})(typeof globalThis !== "undefined" ? globalThis : this);\n')
s=s.replace("const blob = new root.Blob(['(' + RevisaWikiBoot.toString() + ')(globalThis);']","const blob = new root.Blob(['globalThis.RevisaWikiDataV2='+JSON.stringify(root.RevisaWikiDataV2)+';\\n(' + RevisaWikiBoot.toString() + ')(globalThis);']")
bootstrap=(R/'build/module_bootstrap_v2_3.js').read_text().replace('2.2.1','2.3.0').replace('_v2_2_1','_v2_3');(W/'module_bootstrap_v2_3.js').write_text(bootstrap)
(O/'RevisaWiki_v2_3.js').write_text(bootstrap.replace('__CORE_BOOT__',s))
for kind in ['common_js','comunitario']:
 (O/f'Carregador_{kind}_RevisaWiki_v2_3.js').write_text((R/f'dist/2.2.1/Carregador_{kind}_RevisaWiki_v2_2_1.js').read_text().replace('2.2.1','2.3.0'))
for p in O.glob('*.js'):subprocess.run([NODE,'--check',str(p)],check=True)
files={p.name:{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}for p in O.glob('*.js')};assert files['RevisaWiki_v2_3.js']['bytes']<2097152 and files['RevisaWiki_v2_3_dados.js']['bytes']<2097152

assert files==expected['files'],'Generated bytes differ from the tested release.'
print('Rebuilt the exact tested 2.3.0 program and data.')
